170	const DEDUCTIBLE = 100;
171	const CAP_MULTIPLIER = 2;
172	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
173	  sword: 1000,
174	  amulet: 600,
175	  staff: 800,
176	  potion: 400,
177	  rune: 250,
178	  moonstone: 250,
179	};
180	
181	// The cap is twice the insurance sum of the policy's items, taken from the
182	// unmodified insurance values in the price list.
183	const insuranceSumOf = (items: Item[]): number =>
184	  items.reduce((total, item) => total + INSURANCE_VALUE_BY_TYPE[item.type], 0);
185	
186	const HALF_REIMBURSEMENT_PERCENT = 50;
187	const HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD = 8;
188	
189	// The reimbursement rate of a damage depends on the damaged item itself, so
190	// the damage entry is matched against the insured items of its policy.
191	const reimbursableAmountFor = (damage: Damage, item: Item): number =>
192	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_THRESHOLD
193	    ? percentOf(HALF_REIMBURSEMENT_PERCENT, damage.amount)
194	    : damage.amount;
195	
196	// A damage can only be settled against an item the policy actually insures.
197	const insuredItemFor = (damage: Damage, insuredItems: Item[]): Item => {
198	  const item = insuredItems.find(({ type }) => type === damage.itemType);
199	  if (item === undefined) {
200	    throw new Error(`item type not covered by the policy: ${damage.itemType}`);
201	  }
202	  return item;
203	};
204	
205	const payoutForDamage = (damage: Damage, insuredItems: Item[]): number =>
206	  reimbursableAmountFor(damage, insuredItemFor(damage, insuredItems)) -
207	  DEDUCTIBLE;
208	
209	// A damage entry stands for one damaged item, so a policy insuring one sword
210	// cannot back two sword damages.
211	const rejectMoreDamagesThanInsuredItems = (
212	  damages: Damage[],
213	  insuredItems: Item[],
214	): void => {
215	  const insuredCounts = countByType(insuredItems);
216	  const damageCounts = countByType(
217	    damages.map(({ itemType }) => ({ type: itemType })),
218	  );
219	  for (const [type, count] of damageCounts) {
220	    if (count > (insuredCounts.get(type) ?? 0)) {
221	      throw new Error(
222	        `more damage entries than insured items for item type: ${type}`,
223	      );
224	    }
225	  }
226	};
227	
228	// A single unsettleable damage rejects the whole claim, so every damage is
229	// checked before any of them is paid out. The checks are listed in the order
230	// they are reported: the most specific complaint about a damage entry wins.
231	const rejectUnsettleableDamages = (
232	  damages: Damage[],
233	  insuredItems: Item[],
234	): void => {
235	  for (const damage of damages) {
236	    if (damage.amount < 0) {
237	      throw new Error(`negative damage amount: ${damage.amount}`);
238	    }
239	    rejectUnknownItemType(damage.itemType);
240	    insuredItemFor(damage, insuredItems); // throws if the policy does not cover it
241	  }
242	  rejectMoreDamagesThanInsuredItems(damages, insuredItems);
243	};
244	
245	// The cap belongs to the policy, not to the single claim, so successive claims
246	// on the same policy share it and each payout is clamped to what is left.
247	const claimResultFor = (
248	  damages: Damage[],
249	  insuredItems: Item[],
250	  capAlreadyConsumed: number,
251	): ClaimResult => {
252	  rejectUnsettleableDamages(damages, insuredItems);
253	  const remainingCapBefore =
254	    CAP_MULTIPLIER * insuranceSumOf(insuredItems) - capAlreadyConsumed;
255	  const reimbursable = damages.reduce(
256	    (total, damage) => total + payoutForDamage(damage, insuredItems),
257	    0,
258	  );
259	  const payout = Math.floor(Math.min(reimbursable, remainingCapBefore));
260	  return { payout, remainingCap: remainingCapBefore - payout };
261	};
262	
263	// Only a quote issues a contract; a claim step is not a contract and must not
264	// advance the count the follow-up discount is based on.
265	const issuesContract = (step: Step): boolean => step.op !== "claim";
266	
267	export const runScenario = (scenario: Scenario): ScenarioOutcome => {
268	  const capConsumedByPolicy = new Map<number, number>();
269	  let contractsAlreadyIssued = 0;
270	  const results = scenario.steps.map((step) => {
271	    if (issuesContract(step)) {
272	      const premium = premiumFor(
273	        step.items ?? [],
274	        scenario.customer,
275	        contractsAlreadyIssued,
276	      );
277	      contractsAlreadyIssued += 1;
278	      return { premium };
279	    }
280	    const policyIndex = step.policy ?? 0;
281	    const capAlreadyConsumed = capConsumedByPolicy.get(policyIndex) ?? 0;
282	    const result = claimResultFor(
283	      step.incident?.damages ?? [],
284	      scenario.steps[policyIndex].items ?? [],
285	      capAlreadyConsumed,
286	    );
287	    capConsumedByPolicy.set(policyIndex, capAlreadyConsumed + result.payout);
288	    return result;
289	  });
290	  return { results };
291	};
